// Single argument (equivalent to cast)
int i = int(3.14);           // Converts 3.14 to int (truncates to 3)
double d = double(42);       // Converts int to double

// Multiple arguments (requires suitable constructor)
std::string s = std::string(10, 'x');  // Constructs "xxxxxxxxxx"
std::complex<double> c = std::complex<double>(1.0, 2.0);  // 1+2i

// Zero arguments (value-initialization)
int zero = int();            // 0
double dzero = double();     // 0.0
int* ptr = int*();           // nullptr
void v = void();             // Valid, creates void prvalue

// CV-qualifier discarding for non-class types
const int ci = const int();  // Prvalue has type 'int', not 'const int'

// Braced-init-list (C++11)
std::vector<int> vec = std::vector<int>{1, 2, 3};  // List initialization
int arr[] = int[3]{1, 2, 3}; // ERROR: array not allowed with T()
std::pair<int, double> p = std::pair<int, double>{1, 2.5};

