#include <iostream>
#include <string>
#include <complex>
#include <vector>

class Point {
public:
    int x, y;

    // Default constructor
    Point() : x(0), y(0) {
        std::cout << "Point() default: (0, 0)\n";
    }

    // Single-argument constructor
    Point(int val) : x(val), y(val) {
        std::cout << "Point(int): (" << x << ", " << y << ")\n";
    }

    // Two-argument constructor
    Point(int x_val, int y_val) : x(x_val), y(y_val) {
        std::cout << "Point(int, int): (" << x << ", " << y << ")\n";
    }

    void print() const {
        std::cout << "  Point: (" << x << ", " << y << ")\n";
    }
};

int main() {
    std::cout << "=== Functional Notation Type Conversion ===\n\n";

    // 1. Single expression (equivalent to cast)
    std::cout << "Single-expression conversions:\n";
    int i = int(3.14);           // Truncates to 3
    double d = double(42);       // Converts int to double
    std::cout << "  int(3.14) = " << i << "\n";
    std::cout << "  double(42) = " << d << "\n\n";

    // 2. Zero arguments (value-initialization)
    std::cout << "Zero-argument value-initialization:\n";
    int zero = int();            // 0
    double dzero = double();     // 0.0
    int* ptr = int*();           // nullptr
    std::cout << "  int() = " << zero << "\n";
    std::cout << "  double() = " << dzero << "\n";
    std::cout << "  int*() = " << ptr << " (nullptr)\n\n";

    // 3. Class type with single argument
    std::cout << "Class construction - single arg:\n";
    Point p1 = Point(5);         // Calls Point(int)
    p1.print();
    std::cout << "\n";

    // 4. Class type with multiple arguments
    std::cout << "Class construction - multiple args:\n";
    Point p2 = Point(10, 20);    // Calls Point(int, int)
    p2.print();
    std::cout << "\n";

    // 5. Class type with zero arguments
    std::cout << "Class construction - zero args:\n";
    Point p3 = Point();          // Calls Point() default constructor
    p3.print();
    std::cout << "\n";

    // 6. Braced-init-list (C++11)
    std::cout << "Braced-init-list syntax:\n";
    std::vector<int> vec = std::vector<int>{1, 2, 3, 4, 5};
    std::cout << "  vector size: " << vec.size() << "\n";
    std::cout << "  Contents: ";
    for (int v : vec) std::cout << v << " ";
    std::cout << "\n\n";

    // 7. CV-qualifier discarding (non-class types)
    std::cout << "CV-qualifier discarding:\n";
    const int ci = const int();  // Prvalue type is 'int', not 'const int'
    std::cout << "  const int() produces prvalue of type 'int'\n";
    std::cout << "  Value: " << ci << "\n\n";

    // 8. Complex example with std::string
    std::cout << "std::string with multiple args:\n";
    std::string s = std::string(8, '*');  // "********"
    std::cout << "  std::string(8, '*') = \"" << s << "\"\n";

    return 0;
}

// Output:
// === Functional Notation Type Conversion ===
//
// Single-expression conversions:
//   int(3.14) = 3
//   double(42) = 42
//
// Zero-argument value-initialization:
//   int() = 0
//   double() = 0
//   int*() = 0 (nullptr)
//
// Class construction - single arg:
// Point(int): (5, 5)
//   Point: (5, 5)
//
// Class construction - multiple args:
// Point(int, int): (10, 20)
//   Point: (10, 20)
//
// Class construction - zero args:
// Point() default: (0, 0)
//   Point: (0, 0)
//
// Braced-init-list syntax:
//   vector size: 5
//   Contents: 1 2 3 4 5
//
// CV-qualifier discarding:
//   const int() produces prvalue of type 'int'
//   Value: 0
//
// std::string with multiple args:
//   std::string(8, '*') = "********"
